// One terraform console run evaluates many expressions: each becomes a local in a generated file (verbatim, so
// multi-line HCL works), the console prints them as one object of JSON strings. See the inline values design.

export const EVAL_FILE = 'zz_planlens_eval.tf';
export const OVERRIDE_FILE = 'zz_planlens_override.tf';
/** In a module of the copy: one output per expression, read from the root through the module calls. */
export const MODULE_EVAL_FILE = 'zz_planlens_module_eval.tf';
const ERR = '!plan-lens-err';

export type EvalValue =
  | { kind: 'value'; value: unknown }
  | { kind: 'unknown' }
  | { kind: 'sensitive' }
  | { kind: 'error'; message: string };

/** The generated locals; with `bare`, no try(): errors then name their line (see errorsByIndex). */
export function batchFile(exprs: string[], bare = false): { text: string; starts: number[] } {
  const lines = ['# Generated by Plan Lens in its own copy of the configuration: one local per expression shown.', 'locals {'];
  const starts: number[] = [];
  exprs.forEach((e, i) => {
    starts.push(lines.length);
    const body = e.split('\n');
    const wrapped = bare ? [`  __pl_${i} = jsonencode(`, ...body.map((l) => `    ${l}`), '  )'] : [`  __pl_${i} = try(jsonencode(`, ...body.map((l) => `    ${l}`), `  ), "${ERR}")`];
    lines.push(...wrapped);
  });
  lines.push('}', '');
  return { text: lines.join('\n'), starts };
}

/** The one line the console is asked. */
export function consoleQuery(indexes: number[]): string {
  return `{ ${indexes.map((i) => `e${i} = local.__pl_${i}`).join(', ')} }`;
}

/** terraform console's printout of the query object → value per expression index. */
export function parseConsole(stdout: string): Map<number, EvalValue> {
  const out = new Map<number, EvalValue>();
  for (const m of stdout.matchAll(/^\s*"e(\d+)" = (.*)$/gm)) {
    const i = Number(m[1]);
    const raw = m[2].trim();
    if (raw === '(known after apply)') out.set(i, { kind: 'unknown' });
    else if (raw === '(sensitive value)') out.set(i, { kind: 'sensitive' });
    else {
      try {
        // An HCL string literal: JSON escapes, plus $${ / %%{ for literal template markers.
        const json = (JSON.parse(raw) as string).replace(/\$\$\{/g, '${').replace(/%%\{/g, '%{');
        out.set(i, json === ERR ? { kind: 'error', message: '' } : { kind: 'value', value: JSON.parse(json) });
      } catch {
        out.set(i, { kind: 'error', message: `unreadable console output: ${raw.slice(0, 60)}` });
      }
    }
  }
  return out;
}

const ANSI = /\x1b\[[0-9;]*m/g;

/** Errors terraform reports in the generated file, by expression index (from `on zz_planlens_eval.tf line N`). */
export function errorsByIndex(stderr: string, starts: number[], file = EVAL_FILE): Map<number, string> {
  const out = new Map<number, string>();
  const text = stderr.replace(ANSI, '').replace(/^[│╷╵]\s?/gm, '');
  for (const block of text.split(/^(?=Error: )/m)) {
    const title = /^Error: (.*)$/m.exec(block)?.[1]?.trim();
    // In the root (`on zz_planlens_eval.tf`) or in a module (`on modules/net/zz_planlens_module_eval.tf`).
    const at = new RegExp(`on (?:\\S*/)?${file.replace(/\./g, '\\.')} line (\\d+)`).exec(block);
    if (!title || !at) continue;
    const line = Number(at[1]) - 1;
    let idx = -1;
    for (let i = 0; i < starts.length; i++) if (starts[i] <= line) idx = i;
    if (idx < 0) continue;
    // The detail line after the source excerpt says what is wrong in this config's own words.
    const detail = block.split('\n').map((l) => l.trim()).filter(Boolean).find((l, k, all) => k > 0 && !/^on |^\d+:|^Error:/.test(l) && all.indexOf(l) > 1);
    if (!out.has(idx)) out.set(idx, detail && detail.length < 140 ? `${title}: ${detail}` : title);
  }
  return out;
}

const IDENT = /^[A-Za-z_][A-Za-z0-9_-]*$/;
const key = (k: string) => (IDENT.test(k) ? k : JSON.stringify(k));

/** A value as HCL on one line, cut to about `max` characters: `{ app = "10.0.0.0/24", db = … }`. */
export function inlineValue(v: unknown, max = 60): string {
  const s = oneLine(v, max + 20);
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

function oneLine(v: unknown, budget: number): string {
  if (v === null) return 'null';
  if (Array.isArray(v)) {
    const parts: string[] = [];
    let used = 2;
    for (const x of v) {
      if (used > budget) { parts.push('…'); break; }
      const s = oneLine(x, budget - used);
      parts.push(s);
      used += s.length + 2;
    }
    return `[${parts.join(', ')}]`;
  }
  if (typeof v === 'object') {
    const entries = Object.entries(v as Record<string, unknown>);
    if (!entries.length) return '{}';
    const parts: string[] = [];
    let used = 4;
    for (const [k, x] of entries) {
      if (used > budget) { parts.push('…'); break; }
      const s = `${key(k)} = ${oneLine(x, budget - used)}`;
      parts.push(s);
      used += s.length + 2;
    }
    return `{ ${parts.join(', ')} }`;
  }
  return JSON.stringify(v);
}

/** A value as indented HCL, for the hover. */
export function prettyValue(v: unknown, indent = ''): string {
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  const inner = indent + '  ';
  if (Array.isArray(v)) {
    if (!v.length) return '[]';
    const flat = oneLine(v, 1e9);
    if (flat.length + indent.length <= 80) return flat;
    return `[\n${v.map((x) => inner + prettyValue(x, inner)).join(',\n')},\n${indent}]`;
  }
  const entries = Object.entries(v as Record<string, unknown>);
  if (!entries.length) return '{}';
  const width = Math.max(...entries.map(([k]) => key(k).length));
  return `{\n${entries.map(([k, x]) => `${inner}${key(k).padEnd(width)} = ${prettyValue(x, inner)}`).join('\n')}\n${indent}}`;
}

/** for_each / count as instances: `3 instances: "app", "db", "pe"`, `2 instances`, `no instances`. */
export function instancesValue(v: unknown, max = 60): string {
  const keys = typeof v === 'number' ? undefined : Array.isArray(v) ? v.map((x) => (typeof x === 'string' ? x : JSON.stringify(x))) : v && typeof v === 'object' ? Object.keys(v) : undefined;
  const n = typeof v === 'number' ? v : keys?.length;
  if (n === undefined) return inlineValue(v, max);
  if (n === 0) return 'no instances';
  const head = `${n} instance${n > 1 ? 's' : ''}`;
  if (!keys) return head;
  const list = keys.map((k) => JSON.stringify(k)).join(', ');
  const s = `${head}: ${list}`;
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

/** The module file of the copy: one output per expression (verbatim, multi-line works); `bare` without try(). */
export function moduleBatchFile(exprs: string[], bare = false): { text: string; starts: number[] } {
  const lines = ['# Generated by Plan Lens in its own copy of the configuration: one output per expression shown.'];
  const starts: number[] = [];
  exprs.forEach((e, i) => {
    starts.push(lines.length);
    const body = e.split('\n').map((l) => `    ${l}`);
    lines.push(`output "__pl_${i}" {`, bare ? '  value = jsonencode(' : '  value = try(jsonencode(', ...body, bare ? '  )' : `  ), "${ERR}")`, '}');
  });
  lines.push('');
  return { text: lines.join('\n'), starts };
}

/** A call of the module from the root: `module "lakebase" { source = "./modules/lakebase" … }`; multi with for_each / count. */
export interface ModuleCall {
  name: string;
  multi: boolean;
}

/**
 * The root's locals that read the module's outputs through every call: one JSON string per expression, an object
 * call → instance key → the instance's JSON string ("" for a call without for_each / count).
 */
export function moduleRootFile(n: number, calls: ModuleCall[]): { text: string; starts: number[] } {
  const lines = ['# Generated by Plan Lens in its own copy of the configuration: module values, read through the calls.', 'locals {'];
  const starts: number[] = [];
  for (let i = 0; i < n; i++) {
    starts.push(lines.length);
    const parts = calls.map((c) => (c.multi ? `${c.name} = { for k, m in module.${c.name} : k => m.__pl_${i} }` : `${c.name} = { "" = module.${c.name}.__pl_${i} }`));
    lines.push(`  __pl_${i} = jsonencode({ ${parts.join(', ')} })`);
  }
  lines.push('}', '');
  return { text: lines.join('\n'), starts };
}

/** One instance of a module and the value there: `module.lakebase`, `module.subnet["app"]`. */
export interface InstanceValue {
  label: string;
  value: EvalValue;
}

/** A module expression's value (from moduleRootFile) → one value per call instance; unknown / sensitive / errors stay whole. */
export function moduleInstances(v: EvalValue): InstanceValue[] {
  if (v.kind !== 'value' || !v.value || typeof v.value !== 'object') return [{ label: '', value: v }];
  const out: InstanceValue[] = [];
  for (const [call, byKey] of Object.entries(v.value as Record<string, Record<string, string>>)) {
    for (const [k, json] of Object.entries(byKey ?? {})) {
      const label = k === '' ? `module.${call}` : /^\d+$/.test(k) ? `module.${call}[${k}]` : `module.${call}[${JSON.stringify(k)}]`;
      let value: EvalValue;
      try {
        value = json === ERR ? { kind: 'error', message: '' } : { kind: 'value', value: JSON.parse(json) };
      } catch {
        value = { kind: 'error', message: 'unreadable value' };
      }
      out.push({ label, value });
    }
  }
  return out.length ? out : [{ label: '', value: { kind: 'error', message: 'no instance of the module in this environment' } }];
}
